// Value: protects=the big screen's dish line names the dish, says who ate it in a room and never on the boss, and a page
// opened on a served dish shows the dish at once (cooking I1, I3); fails_when=a dishLine branch swaps or a hook's first
// frame replays the cooking; why_new=e2e checks the dish card only and never opens a page after 上菜; seam=none;
// no_claim=the timed frames and callbacks (useEffect does not run in renderToStaticMarkup; e2e covers them)
import { describe, expect, it } from "vitest";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { dishLine, useCookStep, useFinaleStep } from "@/components/cooking";

const dish = { name: "史萊姆凍", part: "外膜", method: "冰鎮", comment: "冰冰涼涼。", points: 10, monster: { name: "史萊姆", sprite: "slime" as const, hue: 0 }, room: 0, teamId: "t1" };

describe("dishLine", () => {
  it("names the dish, the team and its 飽足感 in a room; only the dish without a team or on the boss", () => {
    expect(dishLine(dish, "紅隊", false)).toBe("今晚的菜：史萊姆凍！紅隊吃下 10 飽足感。");
    expect(dishLine(dish, "", false)).toBe("今晚的菜：史萊姆凍！");
    expect(dishLine(dish, "紅隊", true)).toBe("今晚的大菜：史萊姆凍！");
  });
});

/** The hook's first frame, as a page that has just opened sees it. */
const first = (hook: () => unknown) => renderToStaticMarkup(createElement(() => String(hook())));

describe("the first cooking frame (cooking I3, R8)", () => {
  it("useCookStep: nothing before 上菜, the dish at once on a page opened after it", () => {
    expect(first(() => useCookStep(null))).toBe("null");
    expect(first(() => useCookStep("7"))).toBe("3");
  });

  it("useFinaleStep: a boss kill seen live starts on the monster, a page opened on the end screen goes to the podium", () => {
    expect(first(() => useFinaleStep(true))).toBe("0");
    expect(first(() => useFinaleStep(false))).toBe("4");
  });
});
